/* POWER-ON-TIME                                                      */
/* ****************************************************************** */
static ssize_t ppc_rtas_poweron_write(struct file *file,
		const char __user *buf, size_t count, loff_t *ppos)
{
	struct rtc_time tm;
	time64_t nowtime;
	int error = parse_number(buf, count, &nowtime);
	if (error)
		return error;

